INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Sumo_Deadlift_with_Chains', 'Sumo Deadlift with Chains', 'legs', ARRAY['legs','legs','arms','legs','back','back','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift. Attempt to keep the ends of the chains away from the plates so you don''t hit them when you lower the weight. Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside'),
('Superman', 'Superman', 'back', ARRAY['legs','legs']::text[], 'bodyweight', 'stretching', 'beginner', 'To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position. Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying. Slowly begin to lower your arms, legs'),
('Supine_Chest_Throw', 'Supine Chest Throw', 'arms', ARRAY['chest','shoulders']::text[], 'other', 'plyometrics', 'beginner', 'This drill is great for chest passes when you lack a partner or a wall of sufficient strength. Lay on the ground on your back with your knees bent. Begin with the ball on your chest, held with both hands on the bottom. Explode up, extending through the elbow to throw the ball directly above you as high as possible. Catch the ball with both hands as it comes down.'),
('Supine_One-Arm_Overhead_Throw', 'Supine One-Arm Overhead Throw', 'core', ARRAY['chest','back','shoulders']::text[], 'other', 'plyometrics', 'beginner', 'Lay on the ground on your back with your knees bent. Hold the ball with one hand, extending the arm fully behind your head. This will be your starting position. Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance. The ball can be thrown to a partner or bounced off of a wall.'),
('Supine_Two-Arm_Overhead_Throw', 'Supine Two-Arm Overhead Throw', 'core', ARRAY['chest','back','shoulders']::text[], 'other', 'plyometrics', 'beginner', 'Lay on the ground on your back with your knees bent. Hold the ball with both hands, extending the arms fully behind your head. This will be your starting position. Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance. The ball can be thrown to a partner or bounced off of a wall.'),
('Suspended_Fallout', 'Suspended Fallout', 'core', ARRAY['chest','back','shoulders']::text[], 'other', 'strength', 'intermediate', 'Adjust the straps so the handles are at an appropriate height, below waist level. Begin standing and grasping the handles. Lean into the straps, moving to an incline push-up position. This will be your starting position. Keeping your arms straight, lean further into the suspension straps, bringing your body closer to the ground, allowing your shoulders to extend, raising your arms up and over your head. Maintain a neutral spine and keep the rest of your body straight, your shoulders being the on'),
('Suspended_Push-Up', 'Suspended Push-Up', 'chest', ARRAY['shoulders','arms']::text[], 'other', 'strength', 'beginner', 'Anchor your suspension straps securely to the top of a rack or other object. Leaning into the straps, take a handle in each hand and move into a push-up plank position. You should be as close to parallel to the ground as you can manage with your arms fully extended, maintaining good posture. Maintaining a straight, rigid torso, descend slowly by allowing the elbows to flex. Continue until your elbows break 90 degrees, pausing before you extend to return to the starting position.'),
('Suspended_Reverse_Crunch', 'Suspended Reverse Crunch', 'core', ARRAY[]::text[], 'other', 'strength', 'beginner', 'Secure a set of suspension straps with the handles hanging about a foot off of the ground. Move yourself into a pushup plank position facing away from the rack. Place your feet into the handles. You should maintain a straight posture, not allowing the hips to sag. This will be your starting position. Begin the movement by flexing the knees and hips, drawing the knees to your torso. As you do so, anteriorly tilt your pelvis, allowing your spine to flex. At the top of the controlled motion, return'),
('Suspended_Row', 'Suspended Row', 'back', ARRAY['arms','back']::text[], 'other', 'strength', 'beginner', 'Suspend your straps at around chest height. Take a handle in each hand and lean back. Keep your body erect and your head and chest up. Your arms should be fully extended. This will be your starting position. Begin by flexing the elbow to initiate the movement. Protract your shoulder blades as you do so. At the completion of the motion pause, and then return to the starting position.'),
('Suspended_Split_Squat', 'Suspended Split Squat', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'strength', 'intermediate', 'Suspend your straps so the handles are 18-30 inches from the floor. Facing away from the setup, place your rear foot into the handle behind you. Keep your head looking forward and your chest up, with your knee slightly bent. This will be your starting position. Descend by flexing the knee and hips, lowering yourself to the ground. Keep your weight on the heel of your foot and maintain your posture throughout the exercise. At the bottom of the movement, reverse the motion, extending through the h'),
('Svend_Press', 'Svend Press', 'chest', ARRAY['arms','shoulders','arms']::text[], 'other', 'strength', 'beginner', 'Begin in a standing position. Press two lightweight plates together with your hands. Hold the plates together close to your chest to create an isometric contraction in your chest muscles. Your fingers should be pointed forward. This is your starting position. Squeeze the plates between your palms and extend your arms directly out in front of you in a controlled motion. Pause at the top of the motion, and then slowly return to the starting position.'),
('T-Bar_Row_with_Handle', 'T-Bar Row with Handle', 'back', ARRAY['arms','back']::text[], 'barbell', 'strength', 'beginner', 'Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end. Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position. Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position. Pull the weight to your upper abdomen by retracting the shoulder blades and flexing the elbows. Do not jerk the weig'),
('Tate_Press', 'Tate Press', 'arms', ARRAY['chest','shoulders']::text[], 'dumbbell', 'strength', 'intermediate', 'Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other. By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Note: when holding the dumbbells in front of you, make sure your arms are wider than shoulder width apart from each other using a pronated (palms forward) grip. Allow your elbows to point out. This is your starting posi'),
('The_Straddle', 'The Straddle', 'legs', ARRAY['legs','legs']::text[], 'other', 'stretching', 'beginner', 'Begin in a seated, upright position. Start by extending your legs in front of you in a V. With your hands on the floor, lean forward as far as possible. Hold for 10 to 20 seconds.'),
('Thigh_Abductor', 'Thigh Abductor', 'legs', ARRAY['legs']::text[], 'machine', 'strength', 'beginner', 'To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position. Slowly press against the machine with your legs to move them away from each other while exhaling. Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper '),
('Thigh_Adductor', 'Thigh Adductor', 'legs', ARRAY['legs','legs']::text[], 'machine', 'strength', 'beginner', 'To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position. Slowly press against the machine with your legs to move them towards each other while exhaling. Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note:'),
('Tire_Flip', 'Tire Flip', 'legs', ARRAY['legs','chest','arms','legs','legs','back','shoulders','back','arms']::text[], 'other', 'strongman', 'intermediate', 'Begin by gripping the bottom of the tire on the tread, and position your feet back a bit. Your chest should be driving into the tire. To lift the tire, extend through the hips, knees, and ankles, driving into the tire and up. As the tire reaches a 45 degree angle, step forward and drive a knee into the tire. As you do so adjust your grip to the upper portion of the tire and push it forward as hard as possible to complete the turn. Repeat as necessary.'),
('Toe_Touchers', 'Toe Touchers', 'core', ARRAY[]::text[], 'bodyweight', 'stretching', 'beginner', 'To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down. Your legs should be touching each other. Slowly elevate your legs up in the air until they are almost perpendicular to the floor with a slight bend at the knees. Your feet should be parallel to the floor. Move your arms so that they are fully extended at a 45 degree angle from the floor. This is the starting position. While keeping y'),
('Torso_Rotation', 'Torso Rotation', 'core', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Stand upright holding an exercise ball with both hands. Extend your arms so the ball is straight out in front of you. This will be your starting position. Rotate your torso to one side, keeping your eyes on the ball as you move. Now, rotate back to the opposite direction. Repeat for 10-20 repetitions.'),
('Trail_Running_Walking', 'Trail Running/Walking', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'cardio', 'beginner', 'Running or hiking on trails will get the blood pumping and heart beating almost immediately. Make sure you have good shoes. While you use the muscles in your calves and buttocks to pull yourself up a hill, the knees, joints and ankles absorb the bulk of the pounding coming back down. Take smaller steps as you walk downhill, keep your knees bent to reduce the impact and slow down to avoid falling. A 150 lb person can burn over 200 calories for 30 minutes walking uphill, compared to 175 on a flat '),
('Trap_Bar_Deadlift', 'Trap Bar Deadlift', 'legs', ARRAY['legs','legs']::text[], 'other', 'strength', 'beginner', 'For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles. Lower your hips, look forward with your head and keep your chest up. Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times. At the completion of the movement, lower the weight back to the ground under control.'),
('Tricep_Dumbbell_Kickback', 'Tricep Dumbbell Kickback', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position. Now,'),
('Tricep_Side_Stretch', 'Tricep Side Stretch', 'arms', ARRAY['shoulders']::text[], 'other', 'stretching', 'beginner', 'Bring right arm across your body and over your left shoulder, holding your elbow with your left hand, until you feel a stretch in your tricep. Then repeat for your other arm.'),
('Triceps_Overhead_Extension_with_Rope', 'Triceps Overhead Extension with Rope', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Attach a rope to a low pulley. After selecting an appropriate weight, grasp the rope with both hands and face away from the cable. Position your hands behind your head with your elbows point straight up. Your elbows should start out flexed, and you can stagger your stance and lean gently away from the machine to create greater stability. This will be your starting position. To perform the movement, extend through the elbow while keeping the upper arm in position, raising your hands above your he'),
('Triceps_Pushdown', 'Triceps Pushdown', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width. Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position. Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicu'),
('Triceps_Pushdown_-_Rope_Attachment', 'Triceps Pushdown - Rope Attachment', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other). Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position. Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the '),
('Triceps_Pushdown_-_V-Bar_Attachment', 'Triceps Pushdown - V-Bar Attachment', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width. Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. This is your starting position. Using the triceps, bring the bar down until it touches the front of your thighs and the '),
('Triceps_Stretch', 'Triceps Stretch', 'arms', ARRAY['back']::text[], 'other', 'stretching', 'beginner', 'Reach your hand behind your head, grasp your elbow and gently pull. Hold for 10 to 20 seconds, then switch sides.'),
('Tuck_Crunch', 'Tuck Crunch', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down. Your legs should be crossed by wrapping one ankle around the other. Slowly elevate your legs up in the air until your thighs are perpendicular to the floor with a slight bend at the knees. Note: Your knees and toes should be parallel to the floor as opposed to the thighs. Move your arms from the floor and cross them so they are resti'),
('Two-Arm_Dumbbell_Preacher_Curl', 'Two-Arm Dumbbell Preacher Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Grab a dumbbell with each arm and place the upper arms on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position. As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched. As you exhale, use the biceps to curl the weights up until your biceps is fully contracted and the dumbbells are at shoulder height. Squeeze the biceps hard for a second at the contracted positio'),
('Two-Arm_Kettlebell_Clean', 'Two-Arm Kettlebell Clean', 'shoulders', ARRAY['legs','legs','legs','back','back']::text[], 'kettlebell', 'strength', 'intermediate', 'Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead. Clean the kettlebells to your shoulders by extending through the legs and hips as you raise the kettlebells towards your shoulders. Rotate your wrists as you do so. Lower the kettlebells back to the starting position and repeat.'),
('Two-Arm_Kettlebell_Jerk', 'Two-Arm Kettlebell Jerk', 'shoulders', ARRAY['legs','legs','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Squat down a few inches and reverse the motion rapidly driving both kettlebells overhead. Immediately after the initial push, squat down again and get under the kettlebells. Once the kettlebells are locked out, stand upright to complete the exercise.'),
('Two-Arm_Kettlebell_Military_Press', 'Two-Arm Kettlebell Military Press', 'shoulders', ARRAY['arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Press the kettlebells up and out. As the kettlebells pass your head, lean into the weights so that the kettlebells are racked behind your head. Make sure to contract your lats, butt, and stomach for added stability.'),
('Two-Arm_Kettlebell_Row', 'Two-Arm Kettlebell Row', 'back', ARRAY['arms','back']::text[], 'kettlebell', 'strength', 'intermediate', 'Place two kettlebells in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab both kettlebells and pull them to your stomach, retracting your shoulder blades and flexing the elbows. Keep your back straight. Lower and repeat.'),
('Underhand_Cable_Pulldowns', 'Underhand Cable Pulldowns', 'back', ARRAY['arms','back','shoulders']::text[], 'cable', 'strength', 'beginner', 'Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar. Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width. As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so'),
('Upper_Back-Leg_Grab', 'Upper Back-Leg Grab', 'legs', ARRAY['back','back']::text[], 'other', 'stretching', 'beginner', 'While seated, bend forward to hug your thighs from underneath with both arms. Keep your knees together and your legs extended out as you bring your chest down to your knees. You can also stretch your middle back by pulling your back away from your knees as your hugging them.'),
('Upper_Back_Stretch', 'Upper Back Stretch', 'back', ARRAY['back']::text[], 'other', 'stretching', 'beginner', 'Clasp fingers together with your thumbs pointing down, round your shoulders as you reach your hands forward.'),
('Upright_Barbell_Row', 'Upright Barbell Row', 'shoulders', ARRAY['back']::text[], 'barbell', 'strength', 'beginner', 'Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position. Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Tip: Your elbows should '),
('Upright_Cable_Row', 'Upright Cable Row', 'back', ARRAY['shoulders']::text[], 'cable', 'strength', 'intermediate', 'Grasp a straight bar cable attachment that is attached to a low pulley with a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The bar should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position. Use your side shoulders to lift the cable bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touc'),
('Upright_Row_-_With_Bands', 'Upright Row - With Bands', 'back', ARRAY['shoulders']::text[], 'bands', 'strength', 'beginner', 'To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position. Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continu'),
('Upward_Stretch', 'Upward Stretch', 'shoulders', ARRAY['chest','back']::text[], 'other', 'stretching', 'beginner', 'Extend both hands straight above your head, palms touching. Slowly push your hands up and back, keeping your back straight.'),
('V-Bar_Pulldown', 'V-Bar Pulldown', 'back', ARRAY['arms','back','shoulders']::text[], 'cable', 'strength', 'intermediate', 'Sit down on a pull-down machine with a V-Bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar. Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position. Using your lats, pull the bar down as you squeeze your shoulder blade'),
('V-Bar_Pullup', 'V-Bar Pullup', 'back', ARRAY['arms','back','shoulders']::text[], 'bodyweight', 'strength', 'beginner', 'Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles. Once you securely place the V-bar, take a hold of the bar from each side and hang from it. Stick your chest out and lean yourself back slightly in order to better engage the lats. This will be your starting position. Using your '),
('Vertical_Swing', 'Vertical Swing', 'legs', ARRAY['legs','legs','shoulders']::text[], 'dumbbell', 'plyometrics', 'beginner', 'Allow the dumbbell to hang at arms length between your legs, holding it with both hands. Keep your back straight and your head up. Swing the dumbbell between your legs, flexing at the hips and bending the knees slightly. Powerfully reverse the motion by extending at the hips, knees, and ankles to propel yourself upward, swinging the dumbell over your head. As you land, absorb the impact through your legs and draw the dumbbell to your torso before the next repetition.'),
('Walking_Treadmill', 'Walking, Treadmill', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'cardio', 'beginner', 'To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout. Treadmills offer convenience, cardiovascular benefits, and usually have less impact than walking outside. When walking, you should move at a moderate to fast pace, not a leisur'),
('Weighted_Ball_Hyperextension', 'Weighted Ball Hyperextension', 'back', ARRAY['legs','legs','back']::text[], 'other', 'strength', 'intermediate', 'To begin, lie down on an exercise ball with your torso pressing against the ball and parallel to the floor. The ball of your feet should be pressed against the floor to help keep you balanced. Place a weighted plate under your chin or behind your neck. This is the starting position. Slowly raise your torso up by bending at the waist and lower back. Remember to exhale during this movement. Hold the contraction on your lower back for a second and lower your torso back down to the starting position'),
('Weighted_Ball_Side_Bend', 'Weighted Ball Side Bend', 'core', ARRAY[]::text[], 'other', 'strength', 'intermediate', 'To begin, lie down on an exercise ball with your left side of the torso (waist, hips and shoulder) pressed against the ball. Your feet should be on the floor while your legs are crossed and hanging from the ball. Hold a weighted plate with your right hand directly to the right side of your head. Tip: Make sure the smooth side of the plate is resting against your head. Place your left arm across your torso so that your palm is on your obliques. There should be a right angle between your left fore'),
('Weighted_Bench_Dip', 'Weighted Bench Dip', 'arms', ARRAY['chest','shoulders']::text[], 'other', 'strength', 'intermediate', 'For this exercise you will need to place a bench behind your back and another one in front of you. With the benches perpendicular to your body, hold on to one bench on its edge with the hands close to your body, separated at shoulder width. Your arms should be fully extended. The legs will be extended forward on top of the other bench. Your legs should be parallel to the floor while your torso is to be perpendicular to the floor. Have your partner place the dumbbell on your lap. Note: This exerc'),
('Weighted_Crunches', 'Weighted Crunches', 'core', ARRAY[]::text[], 'other', 'strength', 'beginner', 'Lie flat on your back with your feet flat on the ground or resting on a bench with your knees bent at a 90 degree angle. Hold a weight to your chest, or you may hold it extended above your torso. This will be your starting position. Now, exhale and slowly begin to roll your shoulders off the floor. Your shoulders should come up off the floor about 4 inches while your lower back remains on the floor. At the top of the movement, flex your abdominals and hold for a brief pause. Then inhale and slow'),
('Weighted_Jump_Squat', 'Weighted Jump Squat', 'legs', ARRAY['legs','legs','legs','back']::text[], 'barbell', 'strength', 'intermediate', 'Position a lightly loaded barbell across the back of your shoulders. You could also use a weighted vest, sandbag, or other type of resistance for this exercise. The weight should be light enough that it doesn''t slow you down significantly. Your feet should be just outside of shoulder width with your head and chest up. This will be your starting position. Using a countermovement, squat partially down and immediately reverse your direction to explode off of the ground, extending through your hips')
